function parseLaurelLimit(value, fallback = 12) {
  const parsed = Number(value);
  return parsed || fallback;
}

module.exports = { parseLaurelLimit };

const assert = require('node:assert/strict');
const { parseLaurelLimit } = require('../src/laurelHarness.js');

assert.equal(parseLaurelLimit(' 12 '), 12);
assert.equal(parseLaurelLimit('0'), 0);
assert.equal(parseLaurelLimit('bad', 15), 15);

